    genericBody: {
      opening:
        "{title} tarkastelee sitä, miten harkitut valinnat voivat parantaa arkea eläinten kanssa pitäen mukavuuden, turvallisuuden ja yksilöllisyyden keskiössä.",
      second:
        "Paras lähestymistapa alkaa eläimen tarkkailusta. Ikä, luonne, terveys, rutiini ja aiemmat kokemukset vaikuttavat siihen, mikä tuntuu hyvältä.",
      heading1: "Mukavuus ensin",
      paragraph1:
        "Kaunis lopputulos ei saa koskaan syntyä hyvinvoinnin kustannuksella. Eläimet tarvitsevat tilaa, aikaa ja mahdollisuuden pitää taukoja.",
      paragraph2:
        "Myös valmistautuminen on tärkeää. Tuttu rutiini, sopivat välineet ja rauhallinen ympäristö tekevät uusista kokemuksista helpompia.",
      heading2: "Harkitut yksityiskohdat merkitsevät",
      paragraph3:
        "Pienet yksityiskohdat tekevät usein suurimman eron. Laatu, turvallisuus, käytännöllinen suunnittelu ja hyvä valmistelu yhdistävät tyylin ja vastuullisuuden.",
      quote:
        "Todellinen luksus alkaa edessämme olevan eläimen ymmärtämisestä.",
      heading3: "Parempi yhteinen kokemus",
      paragraph4:
        "Kun päätökset tehdään eläimen todellisten tarpeiden mukaan, arjesta tulee rauhallisempaa, turvallisempaa ja merkityksellisempää.",
      paragraph5:
        "Tämä filosofia on PETS & DOGUE -ajattelun ytimessä: eläimiä voidaan juhlia kauniisti samalla kun niiden luontoa kunnioitetaan."
    }
