(function () {
  "use strict";

  const SUPPORTED_LANGUAGES = [
    "en",
    "uk",
    "ru",
    "fr",
    "de",
    "es",
    "it",
    "pt",
    "nl",
    "pl",
    "cs",
    "sk",
    "hu",
    "ro",
    "bg",
    "el",
    "sv",
    "da",
    "no",
    "fi",
    "tr",
    "ar",
    "hi"
  ];

  const LOCALES = {
    en: "en-GB",
    uk: "uk-UA",
    ru: "ru-RU",
    fr: "fr-FR",
    de: "de-DE",
    es: "es-ES",
    it: "it-IT",
    pt: "pt-PT",
    nl: "nl-NL",
    pl: "pl-PL",
    cs: "cs-CZ",
    sk: "sk-SK",
    hu: "hu-HU",
    ro: "ro-RO",
    bg: "bg-BG",
    el: "el-GR",
    sv: "sv-SE",
    da: "da-DK",
    no: "nb-NO",
    fi: "fi-FI",
    tr: "tr-TR",
    ar: "ar",
    hi: "hi-IN"
  };

  let i18nSpeechActive = false;
  let i18nSpeechUtterance = null;

  function getLanguage() {
    let language = "";

    if (
      window.PetsDogueLanguage &&
      typeof window.PetsDogueLanguage.getCurrentLanguage === "function"
    ) {
      try {
        const current =
          window.PetsDogueLanguage.getCurrentLanguage();

        if (typeof current === "string") {
          language = current;
        } else if (current && current.code) {
          language = current.code;
        }
      } catch (error) {
        console.warn(
          "Could not read PETS & DOGUE language API.",
          error
        );
      }
    }

    if (!language) {
      language =
        localStorage.getItem(
          "pets_dogue_language"
        ) || "";
    }

    if (!language) {
      language =
        document.documentElement.lang ||
        "en";
    }

    language =
      String(language)
        .toLowerCase()
        .split("-")[0];

    return SUPPORTED_LANGUAGES.includes(
      language
    )
      ? language
      : "en";
  }

  function getTranslation() {
    const language =
      getLanguage();

    return (
      window
        .PetsDogueTranslations
        .article[language] ||
      window
        .PetsDogueTranslations
        .article.en
    );
  }

  function setText(
    selector,
    value
  ) {
    const element =
      document.querySelector(
        selector
      );

    if (
      element &&
      typeof value === "string"
    ) {
      element.textContent =
        value;
    }
  }

  function setTextAt(
    selector,
    index,
    value
  ) {
    const elements =
      document.querySelectorAll(
        selector
      );

    if (
      elements[index] &&
      typeof value === "string"
    ) {
      elements[index]
        .textContent = value;
    }
  }

  function replaceCount(
    template,
    count
  ) {
    return String(template)
      .replace(
        "{count}",
        String(count)
      );
  }

  function replaceTitle(
    template,
    title
  ) {
    return String(template)
      .replace(
        "{title}",
        String(title)
      );
  }

  function getStandardStoryId() {
    const params =
      new URLSearchParams(
        window.location.search
      );

    const requested =
      params.get("story");

    const validStories = [
      "photoshoot",
      "fashion",
      "travel",
      "wellness",
      "rescue",
      "places",
      "volunteers",
      "community"
    ];

    return validStories.includes(
      requested
    )
      ? requested
      : "default";
  }

  function hasCustomArticle() {
    const params =
      new URLSearchParams(
        window.location.search
      );

    return Boolean(
      params.get("id")
    );
  }

  function localizeDate() {
    if (hasCustomArticle()) {
      return;
    }

    const element =
      document.getElementById(
        "articleDate"
      );

    if (!element) {
      return;
    }

    const language =
      getLanguage();

    try {
      element.textContent =
        new Intl.DateTimeFormat(
          LOCALES[language] ||
            LOCALES.en,
          {
            day: "numeric",
            month: "long",
            year: "numeric"
          }
        ).format(
          new Date(
            Date.UTC(
              2026,
              6,
              31
            )
          )
        );
    } catch (error) {
      console.warn(
        "Could not localize article date.",
        error
      );
    }
  }

  function translateTopBar(ui) {
    setText(
      ".account-side:first-child .account-link",
      ui.myAccount
    );

    setText(
      ".account-center",
      ui.edition
    );

    setText(
      ".account-side.right .account-link",
      ui.joinClub
    );
  }

  function translateNavigation(ui) {
    const values = [
      ui.navArticles,
      ui.navFashion,
      ui.navWellness,
      ui.navTravel,
      ui.navPhotos,
      ui.navContests,
      ui.navCommunity,
      ui.navRescue
    ];

    document
      .querySelectorAll(
        ".category-nav a"
      )
      .forEach(
        (element, index) => {
          if (
            typeof values[index] ===
            "string"
          ) {
            element.textContent =
              values[index];
          }
        }
      );
  }

  function translateSideMenu(ui) {
    setText(
      ".side-menu-header h2",
      ui.explore
    );

    const titles = [
      ui.menuHome,
      ui.menuArticles,
      ui.menuGallery,
      ui.menuClub,
      ui.menuRescue
    ];

    const descriptions = [
      ui.menuHomeDesc,
      ui.menuArticlesDesc,
      ui.menuGalleryDesc,
      ui.menuClubDesc,
      ui.menuRescueDesc
    ];

    document
      .querySelectorAll(
        ".menu-item"
      )
      .forEach(
        (item, index) => {
          const title =
            item.querySelector(
              "h3"
            );

          const description =
            item.querySelector(
              "p"
            );

          if (
            title &&
            titles[index]
          ) {
            title.textContent =
              titles[index];
          }

          if (
            description &&
            descriptions[index]
          ) {
            description.textContent =
              descriptions[index];
          }
        }
      );
  }

  function translateToolbar(ui) {
    const listen =
      document.getElementById(
        "listenButton"
      );

    if (listen) {
      listen.textContent =
        i18nSpeechActive
          ? ui.stop
          : ui.listen;
    }

    const buttons =
      document.querySelectorAll(
        ".article-toolbar .tool-button"
      );

    if (buttons[3]) {
      buttons[3].textContent =
        ui.readingMode;
    }

    if (buttons[4]) {
      buttons[4].textContent =
        ui.share;
    }
  }

  function translateSidebar(ui) {
    const cards =
      document.querySelectorAll(
        ".article-sidebar .sidebar-card"
      );

    if (cards[0]) {
      const heading =
        cards[0].querySelector(
          "h2"
        );

      const paragraph =
        cards[0].querySelector(
          "p"
        );

      if (heading) {
        heading.textContent =
          ui.aboutAuthor;
      }

      if (paragraph) {
        paragraph.textContent =
          ui.authorText;
      }
    }

    if (cards[1]) {
      const heading =
        cards[1].querySelector(
          "h2"
        );

      const paragraph =
        cards[1].querySelector(
          "p"
        );

      const buttons =
        cards[1]
          .querySelectorAll(
            ".share-button"
          );

      if (heading) {
        heading.textContent =
          ui.shareStory;
      }

      if (paragraph) {
        paragraph.textContent =
          ui.shareStoryText;
      }

      if (buttons[0]) {
        buttons[0].textContent =
          ui.copyLink;
      }

      if (buttons[1]) {
        buttons[1].textContent =
          ui.share;
      }
    }

    if (cards[2]) {
      const heading =
        cards[2].querySelector(
          "h2"
        );

      const paragraph =
        cards[2].querySelector(
          "p"
        );

      const link =
        cards[2].querySelector(
          "a"
        );

      if (heading) {
        heading.textContent =
          ui.joinTheClub;
      }

      if (paragraph) {
        paragraph.textContent =
          ui.joinText;
      }

      if (link) {
        link.textContent =
          ui.joinPETS;
      }
    }
  }

  function translateRelated(ui) {
    setText(
      ".related-title",
      ui.continueReading
    );

    const cards =
      document.querySelectorAll(
        ".related-card"
      );

    const data = [
      {
        label:
          ui.relatedWellnessLabel,
        title:
          ui.relatedWellnessTitle,
        description:
          ui.relatedWellnessDesc
      },
      {
        label:
          ui.relatedFashionLabel,
        title:
          ui.relatedFashionTitle,
        description:
          ui.relatedFashionDesc
      },
      {
        label:
          ui.relatedTravelLabel,
        title:
          ui.relatedTravelTitle,
        description:
          ui.relatedTravelDesc
      }
    ];

    cards.forEach(
      (card, index) => {
        const item =
          data[index];

        if (!item) {
          return;
        }

        const label =
          card.querySelector(
            ".related-copy span"
          );

        const title =
          card.querySelector(
            ".related-copy h3"
          );

        const description =
          card.querySelector(
            ".related-copy p"
          );

        if (label) {
          label.textContent =
            item.label;
        }

        if (title) {
          title.textContent =
            item.title;
        }

        if (description) {
          description.textContent =
            item.description;
        }
      }
    );
  }

  function translateFooter(ui) {
    setText(
      "footer > p",
      ui.footerSubtitle
    );

    const values = [
      ui.footerHome,
      ui.footerArticles,
      ui.footerPhotos,
      ui.footerClub,
      ui.footerRescue,
      ui.footerPrivacy,
      ui.footerContact
    ];

    document
      .querySelectorAll(
        ".footer-links a"
      )
      .forEach(
        (element, index) => {
          if (
            typeof values[index] ===
            "string"
          ) {
            element.textContent =
              values[index];
          }
        }
      );

    setText(
      ".admin-small",
      ui.footerAdmin
    );
  }

  function createGenericBody(
    translation,
    story
  ) {
    const body =
      translation.genericBody;

    return [
      {
        type: "p",
        text:
          replaceTitle(
            body.opening,
            story.title
          )
      },
      {
        type: "p",
        text: body.second
      },
      {
        type: "h2",
        text: body.heading1
      },
      {
        type: "p",
        text: body.paragraph1
      },
      {
        type: "p",
        text: body.paragraph2
      },
      {
        type: "h2",
        text: body.heading2
      },
      {
        type: "p",
        text: body.paragraph3
      },
      {
        type: "quote",
        text: body.quote
      },
      {
        type: "h2",
        text: body.heading3
      },
      {
        type: "p",
        text: body.paragraph4
      },
      {
        type: "p",
        text: body.paragraph5
      }
    ];
  }

  function renderArticleBody(
    blocks,
    tags
  ) {
    const container =
      document.getElementById(
        "articleContent"
      );

    if (!container) {
      return;
    }

    container.innerHTML = "";

    blocks.forEach(
      (block) => {
        if (
          !block ||
          !block.type
        ) {
          return;
        }

        if (
          block.type === "p"
        ) {
          const paragraph =
            document.createElement(
              "p"
            );

          paragraph.textContent =
            block.text || "";

          container.appendChild(
            paragraph
          );

          return;
        }

        if (
          block.type === "h2"
        ) {
          const heading =
            document.createElement(
              "h2"
            );

          heading.textContent =
            block.text || "";

          container.appendChild(
            heading
          );

          return;
        }

        if (
          block.type === "quote"
        ) {
          const quote =
            document.createElement(
              "blockquote"
            );

          quote.textContent =
            block.text || "";

          container.appendChild(
            quote
          );

          return;
        }

        if (
          block.type === "image" &&
          block.src
        ) {
          const image =
            document.createElement(
              "img"
            );

          image.className =
            "article-photo";

          image.src =
            block.src;

          image.alt =
            block.alt || "";

          container.appendChild(
            image
          );

          if (block.caption) {
            const caption =
              document.createElement(
                "span"
              );

            caption.className =
              "image-caption";

            caption.textContent =
              block.caption;

            container.appendChild(
              caption
            );
          }
        }
      }
    );

    if (
      Array.isArray(tags) &&
      tags.length
    ) {
      const tagsContainer =
        document.createElement(
          "div"
        );

      tagsContainer.className =
        "article-tags";

      tags.forEach(
        (tag) => {
          const item =
            document.createElement(
              "span"
            );

          item.className =
            "article-tag";

          item.textContent =
            tag;

          tagsContainer
            .appendChild(item);
        }
      );

      container.appendChild(
        tagsContainer
      );
    }
  }

  function renderStandardStory(
    translation
  ) {
    if (hasCustomArticle()) {
      return;
    }

    const storyId =
      getStandardStoryId();

    const story =
      translation.stories[
        storyId
      ] ||
      translation.stories.default;

    const heroImage =
      document.getElementById(
        "articleHeroImage"
      );

    const category =
      document.getElementById(
        "articleCategory"
      );

    const title =
      document.getElementById(
        "articleTitle"
      );

    const intro =
      document.getElementById(
        "articleIntro"
      );

    const author =
      document.getElementById(
        "articleAuthor"
      );

    const readingTime =
      document.getElementById(
        "readingTime"
      );

    if (
      heroImage &&
      story.image
    ) {
      heroImage.src =
        story.image;

      heroImage.alt =
        story.title || "";
    }

    if (category) {
      category.textContent =
        story.category || "";
    }

    if (title) {
      title.textContent =
        story.title || "";
    }

    if (intro) {
      intro.textContent =
        story.intro || "";
    }

    if (author) {
      author.textContent =
        translation.ui.author;
    }

    if (readingTime) {
      readingTime.textContent =
        replaceCount(
          translation
            .ui
            .readingTime,
          story.minutes || 6
        );
    }

    const body =
      Array.isArray(story.body)
        ? story.body
        : createGenericBody(
            translation,
            story
          );

    renderArticleBody(
      body,
      story.tags || []
    );

    document.title =
      `${story.title} | PETS & DOGUE`;

    const meta =
      document.querySelector(
        'meta[name="description"]'
      );

    if (meta) {
      meta.setAttribute(
        "content",
        story.intro || ""
      );
    }
  }

  function setPageDirection() {
    const language =
      getLanguage();

    document.documentElement.lang =
      language;

    document.documentElement.dir =
      language === "ar"
        ? "rtl"
        : "ltr";

    document.body.dir =
      language === "ar"
        ? "rtl"
        : "ltr";
  }

  function applyArticleLanguage() {
    const translation =
      getTranslation();

    if (!translation) {
      return;
    }

    setPageDirection();

    translateTopBar(
      translation.ui
    );

    translateNavigation(
      translation.ui
    );

    translateSideMenu(
      translation.ui
    );

    translateToolbar(
      translation.ui
    );

    translateSidebar(
      translation.ui
    );

    translateRelated(
      translation.ui
    );

    translateFooter(
      translation.ui
    );

    renderStandardStory(
      translation
    );

    localizeDate();
  }

  function stopArticleSpeech() {
    if (
      "speechSynthesis" in
      window
    ) {
      window.speechSynthesis
        .cancel();
    }

    i18nSpeechActive =
      false;

    i18nSpeechUtterance =
      null;

    const button =
      document.getElementById(
        "listenButton"
      );

    if (button) {
      button.classList.remove(
        "active"
      );

      button.textContent =
        getTranslation()
          .ui
          .listen;
    }
  }

  window.toggleSpeech =
    function () {
      const translation =
        getTranslation();

      const button =
        document.getElementById(
          "listenButton"
        );

      if (
        !(
          "speechSynthesis" in
          window
        )
      ) {
        alert(
          translation
            .ui
            .audioUnsupported
        );

        return;
      }

      if (i18nSpeechActive) {
        stopArticleSpeech();
        return;
      }

      const title =
        document.getElementById(
          "articleTitle"
        );

      const intro =
        document.getElementById(
          "articleIntro"
        );

      const content =
        document.getElementById(
          "articleContent"
        );

      const text = [
        title
          ? title.textContent
          : "",
        intro
          ? intro.textContent
          : "",
        content
          ? content.innerText
          : ""
      ]
        .filter(Boolean)
        .join(". ");

      i18nSpeechUtterance =
        new SpeechSynthesisUtterance(
          text
        );

      i18nSpeechUtterance.rate =
        0.95;

      i18nSpeechUtterance.pitch =
        1;

      i18nSpeechUtterance.lang =
        LOCALES[
          getLanguage()
        ] || "en-GB";

      i18nSpeechUtterance.onend =
        stopArticleSpeech;

      i18nSpeechUtterance.onerror =
        stopArticleSpeech;

      window.speechSynthesis
        .cancel();

      window.speechSynthesis
        .speak(
          i18nSpeechUtterance
        );

      i18nSpeechActive =
        true;

      if (button) {
        button.classList.add(
          "active"
        );

        button.textContent =
          translation.ui.stop;
      }
    };

  window.copyArticleLink =
    function () {
      const translation =
        getTranslation();

      const url =
        window.location.href;

      if (
        navigator.clipboard &&
        typeof navigator.clipboard
          .writeText ===
          "function"
      ) {
        navigator.clipboard
          .writeText(url)
          .then(
            function () {
              alert(
                translation
                  .ui
                  .copied
              );
            }
          )
          .catch(
            function () {
              alert(
                `${translation.ui.copyFallback} ${url}`
              );
            }
          );

        return;
      }

      alert(
        `${translation.ui.copyFallback} ${url}`
      );
    };

  window.shareArticle =
    function () {
      const title =
        document.getElementById(
          "articleTitle"
        );

      const intro =
        document.getElementById(
          "articleIntro"
        );

      if (
        navigator.share &&
        typeof navigator.share ===
          "function"
      ) {
        navigator
          .share({
            title: title
              ? title.textContent
              : "PETS & DOGUE",
            text: intro
              ? intro.textContent
              : "",
            url:
              window.location.href
          })
          .catch(
            function () {}
          );

        return;
      }

      window.copyArticleLink();
    };

  function handleLanguageChange() {
    stopArticleSpeech();

    window.setTimeout(
      applyArticleLanguage,
      0
    );
  }

  window.addEventListener(
    "petsdogue:languagechange",
    handleLanguageChange
  );

  window.addEventListener(
    "languagechange",
    handleLanguageChange
  );

  window.addEventListener(
    "storage",
    function (event) {
      if (
        event.key ===
        "pets_dogue_language"
      ) {
        handleLanguageChange();
      }
    }
  );

  if (
    document.readyState ===
    "loading"
  ) {
    document.addEventListener(
      "DOMContentLoaded",
      function () {
        window.setTimeout(
          applyArticleLanguage,
          0
        );
      },
      {
        once: true
      }
    );
  } else {
    window.setTimeout(
      applyArticleLanguage,
      0
    );
  }
})();
